import type {
  CompositionSection,
  CaseInformation,
  ExplorerGroup,
  ExplorerItem,
  InspectorView,
  ScenarioId,
  StartCenterPresentation,
} from "../../../studio/src/clients/presentation";

const item = (
  id: string,
  label: string,
  detail: string,
  kind: ExplorerItem["kind"],
  material?: string,
  posture?: ExplorerItem["posture"],
): ExplorerItem => ({ id, label, detail, kind, material, posture });

const group = (
  label: string,
  items: readonly ExplorerItem[],
  note?: string,
): ExplorerGroup => ({ label, items, note });

const inspect = (
  eyebrow: string,
  title: string,
  description: string,
  facts: readonly [string, string][],
  note?: string,
): InspectorView => ({
  eyebrow,
  title,
  description,
  facts: facts.map(([label, value]) => ({ label, value })),
  note,
});

